import {
	Component,
	Element,
	Event,
	Fragment,
	Host,
	Prop,
	h,
} from "@stencil/core";
import type { EventEmitter } from "@stencil/core";
import { caretLeft, caretRight } from "../../../icons";
import { generateShortID } from "../../utils/function-helper";

import getBootstrapConfig from "../../utils/getBootstrapConfig";

import type { Step } from "./stepper.d";
import { generateMainStep, generateSubStep } from "./stepper.render";

/**
 * @since 1.0.9
 * @status stable
 *
 * @slot left - Left side nav area
 * @slot header - header slot of the main area
 * @slot content - Step view
 * @slot footer - header slot of the main area, usually renders nav buttons
 *
 * @data-testid back - The back button
 * @data-testid next - The next button
 * @data-testid cancel - The cancel button
 * @data-testid collapse-button - The collapse button
 * @data-testid steps-container - The container of all steps
 * @data-testid {step.id} - Each step with id
 */
@Component({
	tag: "hbr-stepper",
	styleUrl: "stepper.scss",
	shadow: false,
})
export class HbrStepper {
	private static readonly DEFAULT_STEP_PANEL_WIDTH = 320;

	private static readonly MIN_STEP_PANEL_WIDTH = 200;

	private static readonly MAX_STEP_PANEL_WIDTH = 400;

	@Element() host: HTMLHbrMenuElement;

	private defaultAria: {
		role: string;
		label?: string;
		step: string;
		completed?: string;
		collapseBtnAriaExpand: string;
		collapseBtnAriaCollapse: string;
	} = {
		role: "tablist",
		label: "Stepper",
		step: "step",
		completed: "Completed",
		collapseBtnAriaExpand: "Expand panel",
		collapseBtnAriaCollapse: "Collapse panel",
	};

	private stepperId: string = generateShortID();

	/** List of steps to be rendered by the stepper */
	@Prop() steps: Array<Step>;

	/** id of the active step */
	@Prop() activeStepId: string;

	/** enabled state of Cancel button in the footer */
	@Prop() cancelEnabled = true;
	/** visibility state of Cancel button in the footer */
	@Prop() cancelVisible = true;
	/** Label of Cancel button in the footer */
	@Prop() cancelLabel = "Cancel";

	/** enabled state of Cancel button in the footer */
	@Prop() secondaryEnabled = true;
	/** visibility state of Cancel button in the footer */
	@Prop() secondaryVisible = true;
	/** Label of Cancel button in the footer */
	@Prop() secondaryLabel = "Back";

	/** enabled state of Cancel button in the footer */
	@Prop() primaryEnabled = true;
	/** visibility state of Cancel button in the footer */
	@Prop() primaryVisible = true;
	/** Label of Cancel button in the footer */
	@Prop() primaryLabel = "Next";

	/** visibility state of Cancel button in the footer */
	@Prop() changesSavedVisible = true;
	/** Label of Cancel button in the footer */
	@Prop() changesSavedLabel = "All changes saved";

	@Prop() hideLeft = false;

	@Prop() raisedFooter = false;

	/** Show the button that collapses left bar */
	@Prop({ reflect: true }) collapsible = true;

	/** Is the nav in collapsed state */
	@Prop({ reflect: true }) collapsed = false;

	@Prop({ reflect: true }) direction: "row" | "column" = "column";

	/**
	 * Width of the expanded step panel in pixels.
	 * Values are clamped to the approved 200px-400px range.
	 */
	@Prop({ reflect: true }) stepPanelWidth = HbrStepper.DEFAULT_STEP_PANEL_WIDTH;

	/**
	 * aria accessibility attributes for the stepper
	 * defaults to:
	 * aria={role: "tablist", collapseBtnAriaExpand: "Expand panel", collapseBtnAriaCollapse: "Collapse panel"}
	 * From Starting from version v2.10.3, the Multi-Page Form will support the aria role="list". The external panel can be designated as a region using  or as a form landmark with , with the aria-labelledby attribute appropriately linked to the active step.
	 */
	@Prop() aria: {
		collapseBtnAriaExpand?: string;
		collapseBtnAriaCollapse?: string;
		role?: string;
		step?: string;
		completed?: string;
	};

	/** event emitted when any of navigational elements are clicked. event.detail has the "type" of change event and clicked "step" */
	@Event({ eventName: "hbr-step-change" }) hbrStepChange: EventEmitter;

	/** the sidenav is collapsed */
	@Event({ eventName: "hbr-collapse" }) hbrCollapse: EventEmitter;

	/** the sidenav is collapsed */
	@Event({ eventName: "hbr-expand" }) hbrExpand: EventEmitter;

	private shouldDisableActiveStepTabFocus() {
		return this.direction === "row" && !!this.host.closest("hbr-modal");
	}

	private syncModalRowCurrentStepTabindex() {
		if (!this.shouldDisableActiveStepTabFocus()) return;

		const tabs = this.host.querySelectorAll<HTMLHbrTabElement>("hbr-tab");
		tabs.forEach((tab) => {
			const base = tab.shadowRoot?.querySelector<HTMLElement>("[part='base']");
			const stepIconButton = tab.querySelector(
				"[slot='prefix'] hbr-button",
			) as HTMLHbrButtonElement | null;
			if (tab.active) {
				tab.setAttribute("tabindex", "-1");
				base?.setAttribute("tabindex", "-1");
				stepIconButton?.setAttribute("tabindex", "-1");
				void stepIconButton?.removeFocus?.();
			} else if (
				stepIconButton &&
				!tab.disabled &&
				!tab.classList.contains("hbr-stepper--tab-hidden")
			) {
				stepIconButton.removeAttribute("tabindex");
			}
		});
	}

	componentDidRender() {
		this.syncModalRowCurrentStepTabindex();
	}

	handleStepFocusIn = async (event: FocusEvent) => {
		if (this.direction !== "row") return;

		const tab = event.currentTarget as HTMLHbrTabElement | null;
		const target = event.target as HTMLElement | null;
		const stepIconButton = tab?.querySelector(
			"[slot='prefix'] hbr-button",
		) as HTMLHbrButtonElement | null;

		if (!tab || !target || !stepIconButton) return;
		if (this.shouldDisableActiveStepTabFocus() && tab.active) {
			await tab.removeFocus?.();
			await stepIconButton.removeFocus?.();
			return;
		}
		if (target === stepIconButton) return;

		await stepIconButton.setFocus?.();
	};

	handleStepChange(actionType, curStep, isSubStep?) {
		let calcStep = null;
		let isCalcSubStep = null;
		if (actionType === "next" || actionType === "back") {
			let stepIndex = -1;
			let subStepIndex = -1;
			for (const [stepIdx, step] of this.steps.entries()) {
				if (step.id === curStep.id) {
					stepIndex = stepIdx;
					break;
				}
				if (step.subSteps) {
					for (const [subStepIdx, subStep] of step.subSteps.entries()) {
						if (subStep.id === curStep.id) {
							stepIndex = stepIdx;
							subStepIndex = subStepIdx;
							break;
						}
					}
				}
			}

			if (actionType === "next") {
				if (subStepIndex === -1) {
					if (
						stepIndex === this.steps.length - 1 &&
						!this.steps[stepIndex].subSteps?.length
					) {
						calcStep = null;
						isCalcSubStep = false;
					} else {
						if (this.steps[stepIndex].subSteps?.length) {
							calcStep = this.steps[stepIndex].subSteps[0];
							isCalcSubStep = true;
						} else {
							calcStep = this.steps[stepIndex + 1];
							isCalcSubStep = false;
						}
					}
				} else {
					if (this.steps[stepIndex].subSteps.length > subStepIndex + 1) {
						calcStep = this.steps[stepIndex].subSteps[subStepIndex + 1];
						isCalcSubStep = true;
					} else {
						if (this.steps.length > stepIndex + 1) {
							calcStep = this.steps[stepIndex + 1];
							isCalcSubStep = false;
						} else {
							calcStep = null;
							isCalcSubStep = false;
						}
					}
				}
			} else if (actionType === "back") {
				if (subStepIndex === -1) {
					if (stepIndex === 0) {
						calcStep = null;
						isCalcSubStep = false;
					} else {
						if (this.steps[stepIndex - 1].subSteps?.length) {
							isCalcSubStep = true;
							calcStep =
								this.steps[stepIndex - 1].subSteps[
									this.steps[stepIndex - 1].subSteps.length - 1
								];
						} else {
							calcStep = this.steps[stepIndex - 1];
							isCalcSubStep = false;
						}
					}
				} else {
					if (subStepIndex > 0) {
						calcStep = this.steps[stepIndex].subSteps[subStepIndex - 1];
						isCalcSubStep = true;
					} else {
						calcStep = this.steps[stepIndex];
						isCalcSubStep = false;
					}
				}
			}
		}

		this.hbrStepChange.emit({
			type: actionType,
			step: actionType === "side-nav" ? curStep : calcStep,
			isSubStep: actionType === "side-nav" ? isSubStep : isCalcSubStep,
		});
	}

	handleCollapseClick() {
		this.collapsed = !this.collapsed;
		if (this.collapsed) this.hbrCollapse.emit();
		else this.hbrExpand.emit();
	}

	private getExpandedStepPanelWidth() {
		const normalizedWidth = Number(this.stepPanelWidth);

		if (Number.isNaN(normalizedWidth)) {
			return HbrStepper.DEFAULT_STEP_PANEL_WIDTH;
		}

		return Math.min(
			HbrStepper.MAX_STEP_PANEL_WIDTH,
			Math.max(HbrStepper.MIN_STEP_PANEL_WIDTH, normalizedWidth),
		);
	}

	render() {
		const _aria = { ...this.defaultAria, ...this.aria };
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		const {
			cancelEnabled,
			cancelVisible,
			cancelLabel,
			secondaryEnabled,
			secondaryVisible,
			secondaryLabel,
			primaryEnabled,
			primaryVisible,
			primaryLabel,
			changesSavedVisible,
			changesSavedLabel,
			hideLeft,
		} = this;
		const { steps, activeStepId, collapsed, collapsible, direction } = this;
		const disableActiveStepTabFocus = this.shouldDisableActiveStepTabFocus();

		const lastVisibleStep = steps
			.slice()
			.reverse()
			.find((it) => it.status !== "hidden");

		const SidebarNav = (
			<div
				class={`hbr-stepper--nav_container hbr-stepper--nav-${this.direction}`}
			>
				<hbr-tab-vertical
					class="hbr-stepper--nav_vertical_tabs"
					sentiment="interact"
					collapsed={collapsed}
					data-testid="steps-container"
					aria={{ role: "none" }}
					role={_aria.role === "tablist" ? "tablist" : "list"}
					aria-orientation={
						_aria.role === "tablist"
							? direction === "column"
								? "vertical"
								: "horizontal"
							: undefined
					}
					aria-label={_aria.label || "Stepper"}
				>
					{steps.map((step: Step, idx) => {
						const mainSteps = generateMainStep(
							step,
							idx,
							lastVisibleStep.id,
							activeStepId,
							this.handleStepChange.bind(this),
							this.handleStepFocusIn,
							customSystemIcons?.check,
							_aria,
							this.stepperId,
							direction === "row",
							disableActiveStepTabFocus,
						);
						if (step.subSteps) {
							const subSteps = step.subSteps.map((subStep: Step, idx) =>
								generateSubStep(
									subStep,
									idx,
									lastVisibleStep.id,
									activeStepId,
									this.handleStepChange.bind(this),
									this.handleStepFocusIn,
									customSystemIcons?.check,
									_aria,
									this.stepperId,
									direction === "row",
									disableActiveStepTabFocus,
								),
							);
							return (
								<Fragment>
									{mainSteps}
									{subSteps}
								</Fragment>
							);
						}
						return mainSteps;
					})}
				</hbr-tab-vertical>
			</div>
		);

		const CtaBar = (
			<div class="hbr-stepper--cta">
				<div class="hbr-stepper--cta_left">
					{cancelVisible ? (
						<hbr-button
							onClick={() => this.handleStepChange("cancel", { id: null })}
							variant="text"
							disabled={!cancelEnabled}
							data-testid="cancel"
						>
							{cancelLabel}
						</hbr-button>
					) : null}
					{changesSavedVisible ? (
						<div class="hbr-stepper--cta_changes-saved">
							{changesSavedLabel}
						</div>
					) : null}
				</div>
				<div class="hbr-stepper--cta_right">
					{secondaryVisible ? (
						<hbr-button
							variant="outline"
							onClick={() =>
								this.handleStepChange("back", { id: activeStepId })
							}
							disabled={!secondaryEnabled}
							data-testid="back"
						>
							{secondaryLabel}
						</hbr-button>
					) : null}
					{primaryVisible ? (
						<hbr-button
							onClick={() =>
								this.handleStepChange("next", { id: activeStepId })
							}
							disabled={!primaryEnabled}
							data-testid="next"
						>
							{primaryLabel}
						</hbr-button>
					) : null}
				</div>
			</div>
		);

		return (
			<Host>
				<div
					part="base"
					style={{
						"--left-width-expanded": `${this.getExpandedStepPanelWidth()}px`,
					}}
					class={{
						"hbr-stepper--": true,
						"hbr-stepper--hideLeft": this.hideLeft,
						"hbr-stepper--collapsed": this.collapsed,
						"hbr-stepper--raisedFooter": this.raisedFooter,
						[`hbr-stepper--direction-${this.direction}`]: true,
					}}
				>
					{hideLeft ? null : (
						<div class="hbr-stepper--left">
							<div class="hbr-stepper--left-header">
								<slot name="left-header" />
							</div>
							<div class="hbr-stepper--left-content">
								<slot name="left">
									{direction === "column" ? SidebarNav : null}
								</slot>
							</div>
							<div class="hbr-stepper--left-footer">
								<slot name="left-footer">
									{collapsible && direction === "column" ? (
										<div class="hbr-stepper--collapse-container">
											<hbr-button
												part="collapse-button"
												variant="outline"
												circle
												sentiment="neutral"
												size="small"
												class="hbr-stepper--collapse-button"
												arialabel={
													collapsed
														? _aria.collapseBtnAriaExpand
														: _aria.collapseBtnAriaCollapse
												}
												onClick={this.handleCollapseClick.bind(this)}
												data-testid="collapse-button"
											>
												<hbr-icon asset={collapsed ? caretRight : caretLeft} />
											</hbr-button>
										</div>
									) : null}
								</slot>
							</div>
						</div>
					)}
					<div class="hbr-stepper--main" id={`stepper-main-${this.stepperId}`}>
						<div class="hbr-stepper--header">
							<slot name="header">
								{direction === "row" ? SidebarNav : null}
							</slot>
						</div>
						<div class="hbr-stepper--content">
							<slot name="content" />
						</div>
						<div class="hbr-stepper--footer">
							<slot name="footer">{CtaBar}</slot>
						</div>
					</div>
				</div>
			</Host>
		);
	}
}
