import { Fragment, h } from "@stencil/core";

import type { Step } from "./stepper.d";

import { check } from "../../../icons/index";

const stopIconOnlyTabClick = (event: MouseEvent) => {
	event.stopPropagation();
};

const stopIconOnlyTabActivation = (event: KeyboardEvent) => {
	if (["Enter", " "].includes(event.key)) {
		event.stopPropagation();
	}
};

const focusStepIcon = (tab: HTMLHbrTabElement) => {
	const stepIconButton = tab.querySelector(
		"[slot='prefix'] hbr-button",
	) as HTMLHbrButtonElement | null;

	void stepIconButton?.setFocus?.({ preventScroll: true });
};

const moveFocusToAdjacentStepIcon = (event: KeyboardEvent) => {
	if (event.key !== "Tab") return false;

	const tab = (event.currentTarget as HTMLElement).closest(
		"hbr-tab",
	) as HTMLHbrTabElement | null;
	if (!tab) return false;

	const tabList = tab.closest("hbr-tab-vertical");
	const tabs = Array.from(tabList?.querySelectorAll("hbr-tab") || []);
	const tabIndex = tabs.indexOf(tab);
	const direction = event.shiftKey ? -1 : 1;

	for (
		let nextIndex = tabIndex + direction;
		nextIndex >= 0 && nextIndex < tabs.length;
		nextIndex += direction
	) {
		const nextTab = tabs[nextIndex] as HTMLHbrTabElement;
		if (
			!nextTab.active &&
			!nextTab.disabled &&
			!nextTab.classList.contains("hbr-stepper--tab-hidden")
		) {
			event.preventDefault();
			event.stopPropagation();
			focusStepIcon(nextTab);
			return true;
		}
	}

	return false;
};

const handleIconOnlyTabKeyDown = (
	event: KeyboardEvent,
	shouldMoveBetweenStepIcons: boolean,
) => {
	if (shouldMoveBetweenStepIcons && moveFocusToAdjacentStepIcon(event)) {
		return;
	}

	stopIconOnlyTabActivation(event);
};

const generateSubStep = (
	subStep: Step,
	_index: number,
	lastVisibleStepId: string,
	activeStepId: string,
	handleStepChange: (type: string, step: Step, isSubStep: boolean) => void,
	handleStepFocusIn: (event: FocusEvent) => void,
	customCheck,
	aria: { role?: string; step?: string; completed?: string },
	stepperId: string,
	iconOnly = false,
	disableActiveStepTabFocus = false,
) => {
	const isSubStepDisabled = !!subStep.status?.includes("disabled");
	const isSubStepDone = !!subStep.status?.includes("done");
	const supProps = {
		class: {
			"hbr-stepper--tab": true,
			"hbr-stepper--tab-done": isSubStepDone,
			"hbr-stepper--tab-last-visible": subStep.id === lastVisibleStepId,
			"hbr-stepper--tab-sub": true,
			"hbr-stepper--tab-hidden": subStep.status === "hidden",
		},
		key: subStep.label,
		vertical: true,
		sentiment: "interact",
		active: subStep.id === activeStepId,
		intermediate: subStep?.subSteps?.some(
			(subSubStep) => activeStepId === subSubStep.id,
		),
		disabled: isSubStepDisabled || subStep.isInteractive === false,
		...(!iconOnly
			? { "onHbr-click": () => handleStepChange("side-nav", subStep, true) }
			: {}),
		role: aria?.role === "list" ? "listitem" : "tab",
		aria: { role: "none" },
	};
	const stepIconTabidx =
		supProps.disabled || (disableActiveStepTabFocus && supProps.active)
			? "-1"
			: subStep.isInteractive !== false
			  ? "0"
			  : "-1";

	return (
		<hbr-tab
			key={subStep.id}
			{...supProps}
			data-testid={subStep.id}
			onFocusin={handleStepFocusIn}
			{...(aria.role === "list" && supProps.active
				? { "aria-current": "step" }
				: {})}
			{...(supProps.active || supProps.intermediate
				? { "aria-controls": `stepper-main-${stepperId}` }
				: {})}
			{...(aria.role !== "list"
				? supProps.active
					? { "aria-selected": "true" }
					: { "aria-selected": "false" }
				: {})}
			{...(supProps.disabled ? { "aria-disabled": "true" } : {})}
			{...(iconOnly ? { onClick: stopIconOnlyTabClick } : {})}
			{...(iconOnly
				? {
						onKeyDown: (event: KeyboardEvent) =>
							handleIconOnlyTabKeyDown(event, disableActiveStepTabFocus),
				  }
				: {})}
		>
			<div class="hbr-stepper--step_label" title={subStep.label}>
				{subStep.label}
				<div class="hbr-stepper--step_sub-label">{subStep.subtitle}</div>
			</div>
			<div slot="prefix" class="hbr-stepper--step_icon">
				<hbr-button
					size="small"
					disabled={supProps.disabled}
					{...(disableActiveStepTabFocus && supProps.active
						? { tabindex: "-1" }
						: {})}
					tabidx={stepIconTabidx}
					circle
					variant={supProps.active ? "fill" : "outline"}
					sentiment={isSubStepDone || supProps.active ? "interact" : "neutral"}
					{...(iconOnly
						? {
								onClick: (event: MouseEvent) => {
									event.stopPropagation();
									handleStepChange("side-nav", subStep, true);
								},
								onKeyDown: (event: KeyboardEvent) =>
									handleIconOnlyTabKeyDown(event, disableActiveStepTabFocus),
						  }
						: {})}
				>
					{isSubStepDone ? (
						<Fragment>
							<hbr-visually-hidden>{aria.completed}</hbr-visually-hidden>
							<hbr-icon
								class="hbr-stepper--sub_step_icon"
								asset={customCheck || check}
							/>
						</Fragment>
					) : null}
				</hbr-button>
			</div>
		</hbr-tab>
	);
};

const generateMainStep = (
	step: Step,
	index: number,
	lastVisibleStepId: string,
	activeStepId: string,
	handleStepChange: (type: string, step: Step, isSubStep: boolean) => void,
	handleStepFocusIn: (event: FocusEvent) => void,
	customCheck,
	aria: { role?: string; step?: string; completed?: string },
	stepperId: string,
	iconOnly = false,
	disableActiveStepTabFocus = false,
) => {
	const isStepDisabled = !!step.status?.includes("disabled");
	const isStepDone = !!step.status?.includes("done");
	const props = {
		class: {
			"hbr-stepper--tab": true,
			"hbr-stepper--tab-done": isStepDone,
			"hbr-stepper--tab-last-visible": step.id === lastVisibleStepId,
			"hbr-stepper--tab-non-interactive": step.isInteractive === false,
			"hbr-stepper--tab-hidden": step.status === "hidden",
		},
		key: step.label,
		vertical: true,
		sentiment: "interact",
		active: step.id === activeStepId,
		intermediate: step?.subSteps?.some(
			(subStep) => activeStepId === subStep.id,
		),
		disabled: isStepDisabled || step.isInteractive === false,
		...(!iconOnly
			? { "onHbr-click": () => handleStepChange("side-nav", step, false) }
			: {}),
		role: aria.role === "list" ? "listitem" : "tab",
		aria: { role: "none" },
	};
	const stepIconTabidx =
		props.disabled || (disableActiveStepTabFocus && props.active)
			? "-1"
			: step.isInteractive !== false
			  ? "0"
			  : "-1";

	return (
		<hbr-tab
			key={step.id}
			{...props}
			data-testid={step.id}
			onFocusin={handleStepFocusIn}
			{...(aria.role === "list" && props.active
				? { "aria-current": "step" }
				: {})}
			{...(aria.role !== "list"
				? props.active
					? { "aria-selected": "true" }
					: { "aria-selected": "false" }
				: {})}
			{...(props.active || props.intermediate
				? { "aria-controls": `stepper-main-${stepperId}` }
				: {})}
			{...(props.disabled ? { "aria-disabled": "true" } : {})}
			{...(iconOnly ? { onClick: stopIconOnlyTabClick } : {})}
			{...(iconOnly
				? {
						onKeyDown: (event: KeyboardEvent) =>
							handleIconOnlyTabKeyDown(event, disableActiveStepTabFocus),
				  }
				: {})}
		>
			<div class="hbr-stepper--step_label" title={step.label}>
				{step.label}
				<div class="hbr-stepper--step_sub-label">{step.subtitle}</div>
			</div>
			<div slot="prefix" class="hbr-stepper--step_icon">
				<hbr-button
					size="small"
					disabled={props.disabled}
					{...(disableActiveStepTabFocus && props.active
						? { tabindex: "-1" }
						: {})}
					tabidx={stepIconTabidx}
					circle
					variant={props.active ? "fill" : "outline"}
					sentiment={isStepDone || props.active ? "interact" : "neutral"}
					{...(iconOnly
						? {
								onClick: (event: MouseEvent) => {
									event.stopPropagation();
									handleStepChange("side-nav", step, false);
								},
								onKeyDown: (event: KeyboardEvent) =>
									handleIconOnlyTabKeyDown(event, disableActiveStepTabFocus),
						  }
						: {})}
				>
					{isStepDone ? (
						<Fragment>
							<hbr-visually-hidden>
								{aria.completed || "Completed"}
							</hbr-visually-hidden>
							<hbr-icon
								class="hbr-stepper--main_step_icon"
								asset={customCheck || check}
							/>
						</Fragment>
					) : (
						<Fragment>
							<hbr-visually-hidden>{aria.step || "Step"}</hbr-visually-hidden>
							{index + 1}
						</Fragment>
					)}
				</hbr-button>
			</div>
		</hbr-tab>
	);
};

export { generateSubStep, generateMainStep };
